import{_ as e,c as r,o as s,H as a}from"./chunks/framework.B03ETCDl.js";const _=JSON.parse('{"title":"비밀번호 재설정 절차","description":"","frontmatter":{"title":"비밀번호 재설정 절차","date":"2024-03-22T22:00+0900"},"headers":[],"relativePath":"posts/reset-password-flow.md","filePath":"posts/reset-password-flow.md","lastUpdated":1780472683000}'),o={name:"posts/reset-password-flow.md"};function l(n,t,p,i,c,h){return s(),r("div",null,[...t[0]||(t[0]=[a('<p>비밀번호 찾기는 대부분의 시스템에서 사용자에게 반드시 요구되는 기능이다. 오래된 레거시 시스템이 아닌 이상 사용자 계정에 대한 비밀번호는 복호화가 불가능하도록 단방향 암호화된 값으로 데이터베이스에 저장된다. 그래서 실질적으로 <strong>비밀번호 찾기 자체의 요구사항은 구현할 수 없다.</strong> 회원가입 시 입력한 비밀번호를 찾을 수는 없으므로 대부분 비밀번호 없이 본인 인증을 통해 로그인할 수 있게 하거나 비밀번호를 재설정할 수 있는 방법을 제공한다.</p><ul><li><a href="https://github.com/password_reset" target="_blank" rel="noreferrer">https://github.com/password_reset</a></li><li><a href="https://account.samsung.com/accounts/odchb/resetPasswordGate" target="_blank" rel="noreferrer">https://account.samsung.com/accounts/odchb/resetPasswordGate</a></li><li><a href="https://sslmember2.gmarket.co.kr/FindPW/FindPW" target="_blank" rel="noreferrer">https://sslmember2.gmarket.co.kr/FindPW/FindPW</a></li><li><a href="https://www.jobplanet.co.kr/users/password/new" target="_blank" rel="noreferrer">https://www.jobplanet.co.kr/users/password/new</a></li></ul><h4 id="비밀번호-재설정-또는-초기화" tabindex="-1">비밀번호 재설정 또는 초기화 <a class="header-anchor" href="#비밀번호-재설정-또는-초기화" aria-label="Permalink to &quot;비밀번호 재설정 또는 초기화&quot;">​</a></h4><p>비밀번호 재설정 절차에 대해서 더 자세하게 알아보도록 하자.</p><ol><li>비밀번호를 찾고자하는 사용자에게 아이디 또는 이메일 입력을 요구</li><li>(Optional) 무분별한 요구를 제한하기 위해서 캡차 또는 <a href="https://www.baeldung.com/spring-bucket4j" target="_blank" rel="noreferrer">요청 제한량</a>을 구현</li><li>사용자에게 <strong>인증</strong>할 수 있는 <strong><a href="https://cheatsheetseries.owasp.org/cheatsheets/Forgot_Password_Cheat_Sheet.html#url-tokens" target="_blank" rel="noreferrer">URL 토큰</a></strong> 링크를 제공</li><li>(Optional) URL 토큰과 함께 인증 코드 입력을 요구</li><li>사용자가 비밀번호 변경을 <strong>완료</strong>했다면 URL 토큰은 즉시 <strong>만료</strong></li><li>사용자에 의해 비밀번호가 변경되었음을 별도 <strong>알림</strong> 제공</li></ol><blockquote><p>URL 쿼리스트링에 포함되는 인증 정보는 JWT 토큰을 사용하지 않는게 일반적입니다.</p></blockquote><p>유튜브 <a href="https://www.youtube.com/watch?v=b5xWS8MYl0Q" target="_blank" rel="noreferrer">제미니의 개발실무</a>에서 개발 요구사항에 대해 그대로 구현하는게 아니라 개발자 입장에서 필요하거나 고려되어야할 부분에 대해서 체크하는 것도 개발자의 역량이라는 부분을 이야기하는 것을 보고 대부분의 시스템에서 요구하는 <strong>비밀번호 찾기</strong>에 대해서 살펴보았다.</p>',7)])])}const g=e(o,[["render",l]]);export{_ as __pageData,g as default};
